document.documentElement.lang='hi';document.title='धीरज एवं नेहा · स्नेह निमंत्रण';
document.querySelector('.hero .eyebrow').textContent='॥ श्री गणेशाय नमः ॥';document.querySelector('.hero .date').textContent='०२ दिसम्बर २०२६ · उत्तर प्रदेश';document.querySelector('.hero .scroll').textContent='स्नेह निमंत्रण ↓';document.querySelector('.sample')?.remove();
document.querySelector('nav').innerHTML='<a href="#invitation">निमंत्रण</a><a href="#celebrations">कार्यक्रम</a><a href="#departure">बारात प्रस्थान</a><a href="#venue">विवाह स्थल</a>';
const programs=[['रामायण पाठ','२७ नवम्बर २०२६','शुक्रवार','20261127'],['मटिमंगरा','२८ नवम्बर २०२६','शनिवार','20261128'],['हल्दी','३० नवम्बर २०२६','सोमवार','20261130'],['सिल मापन (मेहंदी)','०१ दिसम्बर २०२६','मंगलवार','20261201']];
document.querySelector('main').innerHTML=`<section id="invitation" class="hindi-invite"><div class="blessing">॥ श्री गणेशाय नमः ॥</div><h2>स्नेह निमंत्रण</h2><div class="ornament">❧</div><p>आप सभी सादर आमंत्रित हैं।</p><div class="names">धीरज <i>एवं</i> नेहा</div><p>वैदिक विवाह संस्कार</p></section><div class="art-banner" role="img" aria-label="राधा एवं कृष्ण"></div><section id="celebrations"><div class="eyebrow">स्नेह एवं शुभाशीष के साथ</div><h2>मांगलिक कार्यक्रम</h2><p class="small">(वैदिक विवाह संस्कार)</p><div class="events confirmed-events">${programs.map(([name,date,day,key],i)=>`<article class="event"><div class="num">${['१','२','३','४'][i]}</div><h3>${name}</h3><p>${date}<br>${day}</p><button class="btn" data-day="${key}" data-title="${name}">कैलेंडर में जोड़ें</button></article>`).join('')}</div><div class="location-note"><h3>कार्यक्रम स्थल</h3><p>ग्राम : महमदपुर<br>पोस्ट : अजौसी<br>मड़ियाहूँ, जिला : जौनपुर (उत्तर प्रदेश)</p><a class="btn" target="_blank" rel="noopener" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent('महमदपुर अजौसी मड़ियाहूँ जौनपुर उत्तर प्रदेश')}">मानचित्र पर क्षेत्र देखें ↗</a></div></section><section id="departure" class="departure-section"><div class="eyebrow">शुभ यात्रा · शुभ मिलन</div><h2>बारात प्रस्थान एवं प्रातः विदाई</h2><div class="journey-grid"><article><h3>बारात प्रस्थान</h3><p>०२ दिसम्बर २०२६, बुधवार<br><strong>सायं ४:०० बजे</strong></p></article><article><h3>प्रातः विदाई</h3><p>०३ दिसम्बर २०२६<br>गुरुवार</p></article></div><aside class="special-note"><h3>विशेष सूचना</h3><p>बारात हमारे मूल निवास स्थान<br>मरियाहू, जौनपुर (उत्तर प्रदेश)<br>से प्रस्थान करेगी।</p></aside></section><div class="night"><section><div class="eyebrow">मंगल बेला की प्रतीक्षा</div><h2>बारात प्रस्थान तक</h2><div class="count" id="count" aria-label="बारात प्रस्थान तक शेष समय"></div><p class="small" style="color:#f5e8cc">०२ दिसम्बर २०२६ · सायं ४:०० बजे (IST)</p></section></div><section id="venue"><div class="ornament">❧</div><h2>विवाह स्थल</h2><p>ग्राम – कनकपुर (नयेपुर)<br>पोस्ट – भोरी<br>जिला – भदोही (उत्तर प्रदेश)</p><a class="btn" target="_blank" rel="noopener" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent('कनकपुर नयेपुर भोरी भदोही उत्तर प्रदेश')}">मानचित्र पर क्षेत्र देखें ↗</a></section>`;
tick=function(){const seconds=Math.max(0,Math.floor((new Date('2026-12-02T16:00:00+05:30')-Date.now())/1000));document.getElementById('count').innerHTML=[[Math.floor(seconds/86400),'दिन'],[Math.floor(seconds/3600)%24,'घंटे'],[Math.floor(seconds/60)%60,'मिनट'],[seconds%60,'सेकंड']].map(([n,label])=>`<div><strong>${n.toLocaleString('hi-IN',{minimumIntegerDigits:2,useGrouping:false})}</strong><span>${label}</span></div>`).join('')};tick();
document.querySelectorAll('[data-day]').forEach(button=>button.onclick=()=>{const start=button.dataset.day;const d=new Date(Date.UTC(+start.slice(0,4),+start.slice(4,6)-1,+start.slice(6,8)+1));const end=d.toISOString().slice(0,10).replaceAll('-','');const text=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Dhiraj Neha//Wedding//HI','BEGIN:VEVENT','UID:'+start+'@dhiraj-neha','DTSTAMP:20261109T000000Z','DTSTART;VALUE=DATE:'+start,'DTEND;VALUE=DATE:'+end,'SUMMARY:'+button.dataset.title+' - धीरज एवं नेहा','LOCATION:महमदपुर अजौसी मड़ियाहूँ जौनपुर उत्तर प्रदेश','END:VEVENT','END:VCALENDAR'].join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/calendar;charset=utf-8'}));a.download=start+'.ics';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)});
const footer=document.querySelector('.footer');footer.classList.remove('reveal');footer.innerHTML='<div class="footer-parallax-word" aria-hidden="true">शुभ विवाह</div><div class="footer-content"><div class="blessing">॥ राधे कृष्ण ॥</div><h2>आप सभी सादर आमंत्रित हैं।</h2><p>आपका स्नेह एवं आशीर्वाद<br>हमारे जीवन की अनमोल निधि है।</p><div class="names">धीरज एवं नेहा</div><a class="btn" href="#invitation">निमंत्रण पर लौटें ↑</a></div>';const curtain=document.createElement('div');curtain.className='footer-curtain';footer.before(curtain);curtain.append(footer);
document.querySelectorAll('main section,.event,.location-note,.special-note').forEach(el=>{el.classList.add('reveal');observer.observe(el)});
if(!motion){let requested=false;const update=()=>{requested=false;const vh=innerHeight;const art=document.querySelector('.art-banner');const rect=art.getBoundingClientRect();art.style.backgroundPosition=`center ${50+(rect.top/vh)*12}%`;const r=curtain.getBoundingClientRect();const p=Math.max(0,Math.min(1,(vh-r.top)/vh));footer.style.setProperty('--footer-progress',p);document.querySelectorAll('.ornament').forEach(el=>{const y=(el.getBoundingClientRect().top-vh/2)*.055;el.style.transform=`translateY(${Math.max(-25,Math.min(25,y))}px)`})};addEventListener('scroll',()=>{if(!requested){requested=true;requestAnimationFrame(update)}},{passive:true});addEventListener('resize',update);update()}
document.querySelector('.hero .eyebrow').textContent='जय श्री कृष्ण';
// One bounded particle layer loops for the visit, without accumulating DOM nodes.
showerFlowers=function(){if(motion||document.querySelector('.flower-shower.continuous'))return;document.querySelectorAll('.flower-shower').forEach(el=>el.remove());const layer=document.createElement('div');layer.className='flower-shower continuous';layer.setAttribute('aria-hidden','true');for(let i=0;i<28;i++){const petal=document.createElement('span');const variant=Math.floor(Math.random()*9);petal.className='falling-petal';petal.style.left=(Math.random()*100)+'%';petal.style.setProperty('--petal-x',((variant%3)*50)+'%');petal.style.setProperty('--petal-y',(Math.floor(variant/3)*50)+'%');petal.style.setProperty('--size',(17+Math.random()*16)+'px');petal.style.setProperty('--duration',(9+Math.random()*7)+'s');petal.style.setProperty('--delay',(-Math.random()*16)+'s');petal.style.setProperty('--drift',(-85+Math.random()*170)+'px');petal.style.setProperty('--spin',(-400+Math.random()*1000)+'deg');layer.append(petal)}document.body.append(layer)};
if(gate.classList.contains('open'))showerFlowers();
document.addEventListener('visibilitychange',()=>{document.querySelectorAll('.flower-shower.continuous .falling-petal').forEach(el=>el.style.animationPlayState=document.hidden?'paused':'running')});
